/* Годовой маршрут по пяти выбранным предметам. Распределение по главам — авторское,
   тематическая основа — ФРП 2 класса. Тексты учебников не воспроизводятся. */
const CHAPTERS=[{id:1,title:'Старт героя',season:'Осень · основы'},{id:2,title:'Штаб исследователей',season:'Зима · применяем знания'},{id:3,title:'Команда мастеров',season:'Весна · решаем самостоятельно'},{id:4,title:'Финал второго класса',season:'Конец года · объединяем знания'}];
const BASE_TOPIC_KEYS=SUBJECTS.flatMap(s=>s.topics.map(t=>`${s.id}/${t.id}`));
function courseQ(row){const [q,a,b,c,explain]=row;return {q,options:[a,b,c],answer:0,hint:explain,explain};}
function practice(task,criterion){return {task,criteria:[criterion,'Ребёнок объяснил ход работы; ошибки разобраны вместе']};}
function unit(sid,id,title,chapter,rows,task,criterion,reading=''){
 const stages=STAGE_NAMES.map((name,i)=>({name,questions:rows.slice(i*3,i*3+3).map(courseQ)}));
 SUBJECTS.find(s=>s.id===sid).topics.push({id,title,intro:'Исследуй тему, примени знания и объясни решение.',chapter,questions:stages[0].questions,stages,practice:practice(task,criterion),reading});
}
function numericQ(q,n,explain,suffix=''){return [q,`${n}${suffix}`,`${n+1}${suffix}`,`${n===0?2:n-1}${suffix}`,explain];}
const MQ=(q,n,explain,suffix='')=>numericQ(q,n,explain,suffix);
